package io.github.alexistrejo11.pimienta.module.inventory.infrastructure.adapter.output.persistence.repository;
import io.github.alexistrejo11.pimienta.module.inventory.core.domain.*; import io.github.alexistrejo11.pimienta.module.inventory.core.port.output.InventoryCountRepository; import io.github.alexistrejo11.pimienta.module.inventory.infrastructure.adapter.output.persistence.entity.*; import io.github.alexistrejo11.pimienta.module.inventory.infrastructure.adapter.output.persistence.repository.jpa.*; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class InventoryCountRepositoryImpl implements InventoryCountRepository {
 private final InventoryCountSessionJpaRepository sessions; private final InventoryCountResponseJpaRepository responses;
 public InventoryCountRepositoryImpl(InventoryCountSessionJpaRepository s,InventoryCountResponseJpaRepository r){sessions=s;responses=r;}
 public boolean existsActiveByLocationId(long id){return sessions.existsByLocationIdAndStatusIn(id,List.of(InventoryCountSession.Status.DRAFT,InventoryCountSession.Status.SUBMITTED));}
 public Optional<InventoryCountSession> findById(long id){return sessions.findById(id).map(e->{var s=domain(e);s.replaceResponsesForLoad(responses.findBySessionIdOrderByIdAsc(id).stream().map(this::domain).toList());return s;});}
 public InventoryCountSession save(InventoryCountSession s){var e=new InventoryCountSessionJpaEntity();e.setId(s.getId());e.setLocationId(s.getLocationId());e.setCountType(s.getCountType());e.setStatus(s.getStatus());e.setCreatedById(s.getCreatedById());e.setSubmittedById(s.getSubmittedById());e.setApprovedById(s.getApprovedById());e.setCreatedAt(s.getCreatedAt());e.setSubmittedAt(s.getSubmittedAt());e.setApprovedAt(s.getApprovedAt());e.setCancelledAt(s.getCancelledAt());e=sessions.save(e);s.setId(e.getId());for(var r:s.getResponses()){var x=new InventoryCountResponseJpaEntity();x.setId(r.getId());x.setSessionId(e.getId());x.setItemId(r.getItemId());x.setExpectedQuantity(r.getExpectedQuantity());x.setCountedQuantity(r.getCountedQuantity());x.setVariance(r.getVariance());x.setCountedAt(r.getCountedAt());var y=responses.save(x);r.setId(y.getId());}return s;}
 private InventoryCountSession domain(InventoryCountSessionJpaEntity e){var s=new InventoryCountSession();s.setId(e.getId());s.setLocationId(e.getLocationId());s.setCountType(e.getCountType());s.setStatus(e.getStatus());s.setCreatedById(e.getCreatedById());s.setSubmittedById(e.getSubmittedById());s.setApprovedById(e.getApprovedById());s.setCreatedAt(e.getCreatedAt());s.setSubmittedAt(e.getSubmittedAt());s.setApprovedAt(e.getApprovedAt());s.setCancelledAt(e.getCancelledAt());return s;}
 private InventoryCountResponse domain(InventoryCountResponseJpaEntity e){var r=new InventoryCountResponse();r.setId(e.getId());r.setItemId(e.getItemId());r.setExpectedQuantity(e.getExpectedQuantity());r.setCountedQuantity(e.getCountedQuantity());r.setVariance(e.getVariance());r.setCountedAt(e.getCountedAt());return r;}
}
